const items = $('When Called').all();
let fx = null;
try { const f = $('Get FX Rate').first().json.rate; if (f != null && f !== '') fx = Number(f); } catch (e) {}
return items.map(function (itm) {
  const t = itm.json;
  let usd = (t.usd_cost != null && t.usd_cost !== '') ? Number(t.usd_cost) : null;
  let cost_missing = false;
  if (usd == null || isNaN(usd)) { cost_missing = true; usd = null; }
  const cost_pln = (usd != null && fx != null) ? Number((usd * fx).toFixed(6)) : null;
  return { json: {
    clickup_task_id: t.clickup_task_id || null,
    caller_user_id: t.caller_user_id || null,
    process_type: t.process_type || null,
    triggered_by: t.triggered_by || 'explicit_command',
    invocation_type: t.invocation_type || 'explicit',
    model_used: t.model_used || null,
    impact: (t.impact != null && t.impact !== '') ? t.impact : null,
    input_tokens: (t.input_tokens != null && t.input_tokens !== '') ? Number(t.input_tokens) : null,
    output_tokens: (t.output_tokens != null && t.output_tokens !== '') ? Number(t.output_tokens) : null,
    usd_cost: usd,
    fx_rate: fx,
    cost_pln: cost_pln,
    cost_missing: cost_missing
  } };
});

const rows = $input.all();
let logged = 0;
for (const r of rows) { if (r && r.json) logged++; }
return [{ json: { logged: logged } }];
